 // Copyright(c) The Maintainers of Nanvix.
 // Licensed under the MIT License.

 //==================================================================================================
 // Imports
 //==================================================================================================

 use vstd::prelude::*;
 #[cfg(verus_keep_ghost)]
 include!("phys.spec.rs");
 #[cfg(verus_keep_ghost)]
 include!("phys.proof.rs");

 use crate::hal::mem::types::address::{
     Address,
     FrameAddress,
     VirtualAddress,
 };
 use ::arch::mem::{
     self,
     paging::FrameNumber,
 };
 use ::sys::{
     error::{
         Error,
         ErrorCode,
     },
     mm::Alignment,
 };
 #[cfg(verus_keep_ghost)]
 use ::vstd::prelude::*;

 //==================================================================================================
 // Structures
 //==================================================================================================

 ///
 /// # Description
 ///
 /// A type that represents a physical address.
 ///
 #[verus_verify(external_derive)]
 #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
 pub struct PhysicalAddress(VirtualAddress);

 //==================================================================================================
 // Implementations
 //==================================================================================================

 impl PhysicalAddress {
     pub fn from_virtual_address(addr: VirtualAddress) -> Result<Self, Error> {
         // Delegate to the per-platform validator to support sparse physical memory layouts.
         if !crate::hal::platform::is_valid_physical_address(addr) {
             return Err(Error::new(
                 ErrorCode::BadAddress,
                 "address out of bounds of physical memory",
             ));
         }

         Ok(Self(addr))
     }

     pub fn into_virtual_address(self) -> VirtualAddress {
         self.0
     }

     ///
     /// # Description
     ///
     /// Constructs a [`PhysicalAddress`] from a [`FrameAddress`].
     ///
     /// # Parameters
     ///
     /// - `frame_addr`: The frame address.
     ///
     /// # Returns
     ///
     /// A [`PhysicalAddress`] associated with the given `frame_addr`.
     ///
     pub fn from_frame_address(frame_addr: FrameAddress) -> Self {
         let raw_addr: usize = frame_addr.into_raw_value() << mem::FRAME_SHIFT;
         Self(VirtualAddress::new(raw_addr))
     }

     pub fn from_into_frame_address(frame_addr: FrameAddress) -> Self {
         let raw_addr: usize = frame_addr.into_raw_value() << mem::FRAME_SHIFT;
         Self(VirtualAddress::new(raw_addr))
     }
 }

 // Verification-target methods. They live in a dedicated `#[verus_verify]` impl
 // block so that only the in-scope functions are checked (the self-less
 // associated functions `from_mmio_address` / `from_number` require an enclosing
 // `#[verus_verify]` impl to resolve), while the untouched constructors above are
 // left out of verification scope.
 #[verus_verify]
 impl PhysicalAddress {
     ///
     /// # Description
     ///
     /// Constructs a physical address from a memory-mapped I/O address.
     ///
     /// # Parameters
     ///
     /// - `addr`: The memory-mapped I/O address.
     ///
     /// # Return Values
     ///
     /// Upon success, a physical address associated with the given memory-mapped I/O address is
     /// returned. Upon failure, an error is returned instead.
     ///
     /// # Safety
     ///
     /// Behavior is undefined if the provided memory-mapped I/O address is invalid.
     ///
     // Deliberately bypasses the RAM-range validity check (MMIO GPAs may lie
     // outside tracked RAM). On success it is pure identity wrapping
     // (`r@ == addr@`); the `unsafe` contract — that `addr` denotes a valid MMIO
     // frame — is encoded as `requires` (frame-representability) so the result
     // satisfies the type invariant and may later flow into `into_frame_number`.
     #[verus_spec(result =>
         requires
             spec_frame_number(addr@) <= spec_max_frame_number(),
         ensures
             result is Ok,
             result matches Ok(r) ==> r@ == addr@ && r.inv(),
     )]
     pub unsafe fn from_mmio_address(addr: VirtualAddress) -> Result<Self, Error> {
         Ok(Self(addr))
     }

     ///
     /// # Description
     ///
     /// Constructs a [`PhysicalAddress`] from a [`FrameNumber`].
     ///
     /// # Parameters
     ///
     /// - `frame`: The frame number.
     ///
     /// # Returns
     ///
     /// A [`PhysicalAddress`] associated with the given `frame_number`.
     ///
     // The produced address is the frame's base address (`frame * FRAME_SIZE`).
     // The result is page-aligned (`result@ % FRAME_SIZE == 0`) and carries the
     // type invariant (`result.inv()`), so its sole caller can build a `FrameAddress`
     // (alignment) and later project it back with `into_frame_number` (`inv()`).
     #[verus_spec(result =>
         ensures
             result@ == spec_from_number(spec_frame_raw_value(frame)),
             result@ % spec_page_size() == 0,
             result.inv(),
     )]
     pub fn from_number(frame: FrameNumber) -> Self {
         // VERUS DEVIATION (pre-approved: `f(complex_expr)` -> `let x = complex_expr; f(x)`):
         // the `frame * FRAME_SIZE` product is bound to intermediate locals so the
         // proof block below can discharge the no-overflow obligation on them.
         let frame_raw: usize = frame.into_raw_value();
         let page_size: usize = mem::FRAME_SIZE;
         proof! {
             // No-overflow: `frame_raw * page_size <= usize::MAX`. With
             // `frame_raw <= usize::MAX / page_size - 1` and `page_size > 0`, the
             // product stays within `usize`.
             let p: int = spec_page_size();
             let fr: int = spec_frame_raw_value(frame);
             let m: int = usize::MAX as int;
             lemma_fundamental_div_mod(m, p);
             lemma_mod_division_less_than_divisor(m, p);
             assert(p * (m / p) <= m);
             assert(fr * p <= m) by (nonlinear_arith)
                 requires
                     p > 0,
                     fr >= 0,
                     fr <= m / p - 1,
                     p * (m / p) <= m,
             ;
         }
         let addr: usize = frame_raw * page_size;
         proof! {
             // Alignment and invariant follow from `(fr * p) / p == fr <= MAX`.
             lemma_mod_multiples_basic(spec_frame_raw_value(frame), spec_page_size());
             lemma_div_by_multiple(spec_frame_raw_value(frame), spec_page_size());
         }
         Self(VirtualAddress::new(addr))
     }

     // Total projection: yields the containing frame (`self@ / FRAME_SIZE`). The
     // receiver's invariant guarantees the computed index fits a `FrameNumber`,
     // so the internal `unwrap()` never panics.
     #[verus_spec(result =>
         requires
             self.inv(),
         ensures
             spec_frame_raw_value(result) == spec_frame_number(self@),
     )]
     pub fn into_frame_number(self) -> FrameNumber {
         let raw_addr: usize = self.0.into_raw_value();
         // VERUS DEVIATION (pre-approved: `f(complex_expr)` -> `let x = complex_expr; f(x)`):
         // the shift amount is bound to a local so the proof block can relate
         // `raw_addr >> shift` to division by `spec_page_size()`.
         let shift: usize = mem::FRAME_SHIFT;
         proof! {
             // `raw_addr >> shift == raw_addr / 2^shift == self@ / spec_page_size()`,
             // which `self.inv()` bounds by `spec_max_frame_number()`, so the index
             // is representable and `from_raw_value(..).unwrap()` is total.
             lemma_usize_shr_is_div(raw_addr, shift);
         }
         let frame_number: usize = raw_addr >> shift;
         // Safety: the following unwrap is safe because a physical address has a valid frame number.
         FrameNumber::from_raw_value(frame_number).unwrap()
     }
 }

 impl Address for PhysicalAddress {
     ///
     /// # Description
     ///
     /// Instantiates a new [`PhysicalAddress`] from a raw value.
     ///
     /// # Parameters
     ///
     /// - `raw_addr`: The raw value.
     ///
     /// # Returns
     ///
     /// - `Ok(Self)`: The new address.
     /// - `Err(Error::BadAddress)`: If the provided address is invalid.
     ///
     fn from_raw_value(value: usize) -> Result<Self, Error> {
         Self::from_virtual_address(VirtualAddress::from_raw_value(value))
     }

     ///
     /// # Description
     ///
     ///  Aligns the target [`PhysicalAddress`] to the provided `alignment`. If the address is already
     ///  aligned, it is returned as is.
     ///
     /// # Parameters
     ///
     /// - `alignment`: The alignment to align the target address to.
     ///
     /// # Returns
     ///
     /// Upon success, the aligned address is returned. Upon failure, an error is returned instead.
     ///
     fn align_up(&self, align: Alignment) -> Result<Self, Error> {
         let aligned: VirtualAddress = self.0.align_up(align).ok_or_else(|| {
             let reason: &str = "align_up overflow";
             error!(
                 "PhysicalAddress::align_up(): {reason} (addr={:#x}, align={:?})",
                 self.0.into_raw_value(),
                 align
             );
             Error::new(ErrorCode::BadAddress, reason)
         })?;
         Self::from_virtual_address(aligned)
     }

     ///
     /// # Description
     ///
     /// Aligns the target [`PhysicalAddress`] down to the provided `alignment`. If the address is
     /// already aligned, it is returned as is.
     ///
     /// # Parameters
     ///
     /// - `alignment`: The alignment to align the target address to.
     ///
     /// # Returns
     ///
     /// Upon success, the aligned address is returned. Upon failure, an error is returned instead.
     ///
     fn align_down(&self, align: Alignment) -> Result<Self, Error> {
         Self::from_virtual_address(self.0.align_down(align))
     }

     ///
     /// # Description
     ///
     /// Checks if the target [`PhysicalAddress`] is aligned to the provided `alignment`.
     ///
     /// # Parameters
     ///
     /// - `alignment`: The alignment to check.
     ///
     /// # Returns
     ///
     /// Upon success, `true` is returned if the address is aligned, otherwise `false`. Upon failure,
     /// an error is returned instead.
     ///
     fn is_aligned(&self, align: Alignment) -> Result<bool, Error> {
         Ok(self.0.is_aligned(align))
     }

     ///
     /// # Description
     ///
     /// Returns the maximum address for [`PhysicalAddress`].
     ///
     /// # Returns
     ///
     /// The maximum [`PhysicalAddress`].
     ///
     fn max_addr() -> usize {
         crate::hal::platform::max_physical_address()
     }

     fn into_raw_value(self) -> usize {
         self.0.into_raw_value()
     }

     fn as_ptr(&self) -> *const u8 {
         self.0.as_ptr()
     }

     fn as_mut_ptr(&self) -> *mut u8 {
         self.0.as_mut_ptr()
     }
 }

 impl core::fmt::Debug for PhysicalAddress {
     fn fmt(&self, f: &mut core::fmt::Formatter) -> core::fmt::Result {
         write!(f, "{:?}", self.0)
     }
 }

 // The `View` impl for `PhysicalAddress` is verification material; it lives in
 // `phys.spec.rs` (included only under `cfg(verus_keep_ghost)`) so that no
 // verification-only construct is cfg-gated inside this exec source file.

diff --git a/home/ruize/nanvix-phy/src/kernel/src/hal/mem/types/address/phys.spec.rs b/home/ruize/nanvix-phy/src/kernel/src/hal/mem/types/address/phys.spec.rs
index 0000000..0000000 100644
--- a/home/ruize/nanvix-phy/src/kernel/src/hal/mem/types/address/phys.spec.rs
+++ b/home/ruize/nanvix-phy/src/kernel/src/hal/mem/types/address/phys.spec.rs
@@ -1,160 +1,160 @@
 // Copyright(c) The Maintainers of Nanvix.
 // Licensed under the MIT License.

 // PhysicalAddress — Specifications
 //
 // A `PhysicalAddress` abstracts to a single mathematical integer: the raw
 // physical address (`PhysicalAddress@ : int`, defined by the `View` impl in
 // `phys.rs`, delegating to the inner `VirtualAddress`). The only derived notion
 // callers reason about is the *frame* the address lies in
 // (`addr / FRAME_SIZE == addr >> FRAME_SHIFT`), used to index the frame
 // allocator's bitmaps / refcount arrays.
 //
 // Trust-boundary helpers pin the not-yet-verified `arch` `FrameNumber` type and
 // the `arch`/`sys` library-edge constants/methods this module calls. They mirror
 // the existing `sys`/`arch` `assume_specification` boundaries the codebase
 // already draws (`::arch::mem::PAGE_SIZE` in `frame.rs`, the `Address` trait
 // methods in `page.spec.rs` / `kframe.spec.rs`). `spec_page_size()` is the
 // canonical frame size, re-exported from `crate::hal::mem` (defined alongside
 // `FrameAddress`); `FRAME_SIZE == PAGE_SIZE == spec_page_size()`.

 verus! {

 use crate::hal::mem::spec_page_size;
 use vstd::arithmetic::power2::pow2;
 use vstd::arithmetic::div_mod::{
     lemma_fundamental_div_mod,
     lemma_mod_division_less_than_divisor,
     lemma_div_by_multiple,
     lemma_mod_multiples_basic,
 };
 use vstd::bits::lemma_usize_shr_is_div;

 // `FrameNumber` lives in the `arch` crate, which is not Verus-enabled and has no
 // `View`/datatype registration reachable here. Declare it to Verus as an opaque
 // external datatype so it may appear in spec-fn parameters and the
 // `assume_specification`s below. Its internals are not modeled (`external_body`):
 // its abstract index is projected by `spec_frame_raw_value`.
 #[verifier::external_type_specification]
 #[verifier::external_body]
 pub struct ExFrameNumber(FrameNumber);

 // ── Frame-number trust-boundary projections (arch `FrameNumber`) ──────────────
 //
 // `FrameNumber` lives in the `arch` crate, which is not Verus-enabled and has no
 // `View` impl reachable here (orphan rule). Its abstract index is therefore
 // projected by an uninterpreted ghost function, exactly as `view_design.md`
 // prescribes. `spec_max_frame_number()` denotes `FrameNumber::MAX`.

 // The integer index of a frame number (`0 ..= spec_max_frame_number()`).
 pub uninterp spec fn spec_frame_raw_value(frame: FrameNumber) -> int;

 // The largest representable frame number. Mirrors `arch FrameNumber::MAX ==
 // MAX_ADDRESS / FRAME_SIZE - 1 == usize::MAX / FRAME_SIZE - 1`. Interpreting it
 // against `usize::MAX` and `spec_page_size()` is what lets verified constructors
 // discharge their `usize` multiply (no-overflow) obligation: a frame index in
 // `0 ..= spec_max_frame_number()` scaled by `spec_page_size()` stays `<= usize::MAX`.
 pub open spec fn spec_max_frame_number() -> int {
     usize::MAX as int / spec_page_size() - 1
 }

 // ── Derived spec helpers over the View domain (`int`) ─────────────────────────

 // The frame an address lies in: exact integer division, independent of whether
 // the implementation shifts (`>> FRAME_SHIFT`) or divides (`/ FRAME_SIZE`).
 pub open spec fn spec_frame_number(addr_view: int) -> int {
     addr_view / spec_page_size()
 }

 // The base (frame-aligned) address of a frame index: `frame * FRAME_SIZE`.
 pub open spec fn spec_from_number(frame_view: int) -> int {
     frame_view * spec_page_size()
 }

 // ── `arch`/`sys` library-edge `assume_specification`s ─────────────────────────

 // `::arch::mem::FRAME_SIZE` is the frame size (alias of `PAGE_SIZE`), tied to the
 // canonical `spec_page_size()`. It is strictly positive (`== 4096`); positivity is
 // the load-bearing fact for the division/modulo reasoning in the constructors.
 pub assume_specification[ ::arch::mem::FRAME_SIZE ] -> (result: usize)
     ensures
         result == spec_page_size(),
         spec_page_size() > 0,
 ;

 // `::arch::mem::FRAME_SHIFT == log2(FRAME_SIZE)`. Bounded below the pointer width
 // so `raw_addr >> FRAME_SHIFT` is well-defined, and `2^FRAME_SHIFT == FRAME_SIZE`
 // so the shift coincides with division by `spec_page_size()`.
 pub assume_specification[ ::arch::mem::FRAME_SHIFT ] -> (result: usize)
     ensures
         result < usize::BITS,
         pow2(result as nat) == spec_page_size(),
 ;

 // `VirtualAddress::new` now carries a native `#[verus_spec]` in `sys`
 // (`mm::address::virt`), so its contract is imported directly across the crate
 // boundary; a local `assume_specification` here would duplicate it (Verus error:
 // "duplicate specification for ... ::new"). The guaranteed fact is identical
 // (`result@ == value as int`).

 // `<VirtualAddress as Address>::into_raw_value` is pure newtype identity: the
 // returned raw `usize` equals the abstract address. It remains an
 // `assume_specification` trust boundary because this trait-impl method cannot be
 // body-verified in `sys` without marking the whole `impl Address for
 // VirtualAddress` verified, which pulls the sibling `as_ptr`/`as_mut_ptr` methods
 // (unsupported `usize as *const u8` casts) into scope — a Verus front-end
 // limitation (see `verus-ai-logs/verus-unsupported.md`).
 pub assume_specification[ <VirtualAddress as Address>::into_raw_value ](
     addr: VirtualAddress,
 ) -> (result: usize)
     ensures
         result as int == addr@,
 ;

 // `FrameNumber::into_raw_value` projects a frame number to its index; every
 // `FrameNumber` value is in range (`0 ..= MAX`) by construction.
 pub assume_specification[ FrameNumber::into_raw_value ](frame: FrameNumber) -> (result: usize)
     ensures
         result as int == spec_frame_raw_value(frame),
         0 <= spec_frame_raw_value(frame) <= spec_max_frame_number(),
 ;

 // `FrameNumber::from_raw_value` succeeds iff `value <= MAX`, preserving the index.
 pub assume_specification[ FrameNumber::from_raw_value ](value: usize) -> (result: Option<FrameNumber>)
     ensures
         match result {
             Some(f) => value as int <= spec_max_frame_number()
                 && spec_frame_raw_value(f) == value as int,
             None => value as int > spec_max_frame_number(),
